from typing import List, Sequence

def dot(a: Sequence[float], b: Sequence[float]) -> float:
    return sum(x * y for x, y in zip(a, b))

def equality_scores(size: int, query_index: int) -> List[float]:
    query = [float(i == query_index) for i in range(size)]
    return [dot(query, [float(i == key) for i in range(size)]) for key in range(size)]

if __name__ == "__main__":
    print(equality_scores(8, 3))

from typing import List, Sequence

def affine(s: Sequence[float], b: Sequence[float], x: Sequence[float]) -> List[float]:
    return [si * xi + bi for si, bi, xi in zip(s, b, x)]

def fuse(s1: Sequence[float], b1: Sequence[float], s2: Sequence[float], b2: Sequence[float]) -> tuple[List[float], List[float]]:
    return ([u * v for u, v in zip(s2, s1)], [u * v + w for u, v, w in zip(s2, b1, b2)])

if __name__ == "__main__":
    x, s1, b1, s2, b2 = [1.0, 2.0], [2.0, -1.0], [1.0, 3.0], [4.0, 5.0], [-2.0, 1.0]
    sf, bf = fuse(s1, b1, s2, b2)
    print(affine(s2, b2, affine(s1, b1, x)), affine(sf, bf, x))

from itertools import product
from typing import Dict, List, Tuple

def build_table() -> Dict[Tuple[int, ...], List[float]]:
    return {x: [float(sum(x) % 2), float(sum(x))] for x in product((0, 1), repeat=3)}

def exact_lookup(table: Dict[Tuple[int, ...], List[float]], query: Tuple[int, ...]) -> List[float]:
    width = len(next(iter(table.values())))
    return [sum(float(query == key) * value[j] for key, value in table.items()) for j in range(width)]

if __name__ == "__main__":
    table = build_table()
    for x in table:
        assert exact_lookup(table, x) == table[x]
    print("Recovered", len(table), "sequence outputs exactly")

