from typing import Sequence, Tuple, List
def fuse_affine(s1: Sequence[float], b1: Sequence[float], s2: Sequence[float], b2: Sequence[float]) -> Tuple[List[float], List[float]]:
    if not (len(s1) == len(b1) == len(s2) == len(b2)):
        raise ValueError("dimensions must agree")
    return ([s2[i] * s1[i] for i in range(len(s1))], [s2[i] * b1[i] + b2[i] for i in range(len(s1))])

from typing import Sequence
def bilinear_score(matrix: Sequence[Sequence[float]], query: Sequence[float], key: Sequence[float]) -> float:
    if len(matrix) != len(query) or any(len(row) != len(key) for row in matrix):
        raise ValueError("dimensions must agree")
    return sum(query[i] * matrix[i][j] * key[j] for i in range(len(query)) for j in range(len(key)))

